#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, queries;
    cin >> n >> queries;
    vector<long long> values(n);
    for (auto& value : values) cin >> value;
    int start = 0;
    while (queries--) {
        int type, x, y;
        cin >> type >> x >> y;
        if (type == 1) swap(values[(start + x - 1) % n], values[(start + y - 1) % n]);
        else if (type == 2) start = (start + n - 1) % n;
        else cout << values[(start + x - 1) % n] << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    array<array<long long, 46>, 3> count{};
    for (int group = 0; group < 3; ++group) {
        for (int i = 0; i < n; ++i) {
            long long value;
            cin >> value;
            ++count[group][value % 46];
        }
    }
    long long answer = 0;
    for (int first = 0; first < 46; ++first) {
        for (int second = 0; second < 46; ++second) {
            int third = (46 - (first + second) % 46) % 46;
            answer += count[0][first] * count[1][second] * count[2][third];
        }
    }
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, length;
    cin >> n >> length;
    const long long mod = 1000000007;
    vector<long long> ways(n + 1);
    ways[0] = 1;
    for (int step = 1; step <= n; ++step) {
        ways[step] = ways[step - 1];
        if (step >= length) ways[step] = (ways[step] + ways[step - length]) % mod;
    }
    cout << ways[n] << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    const long long mod = 1000000007;
    long long answer = 1;
    for (int die = 0; die < n; ++die) {
        long long faceSum = 0;
        for (int face = 0; face < 6; ++face) {
            long long value;
            cin >> value;
            faceSum += value;
        }
        answer = answer * (faceSum % mod) % mod;
    }
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int queries;
    cin >> queries;
    deque<long long> deck;
    while (queries--) {
        int type;
        long long value;
        cin >> type >> value;
        if (type == 1) deck.push_front(value);
        else if (type == 2) deck.push_back(value);
        else cout << deck[static_cast<size_t>(value - 1)] << '\n';
    }
}
